import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Card,
  CardContent,
  Chip,
  Grid,
  LinearProgress,
  Paper,
  Tab,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Tabs,
  Typography,
} from '@mui/material';
import axios from 'axios';
import PartnerPortalLayout from './PartnerPortalLayout';
import PartnerMsmeCohortPanel from './PartnerMsmeCohortPanel';
import PartnerClusterMisPanel from './PartnerClusterMisPanel';
import PartnerVerificationQueuePanel from './PartnerVerificationQueuePanel';
import { buildApiUrl } from '../../config/apiConfig';
import { formatFixed } from '../../utils/formatNumbers';

interface UsageQuota {
  metric: string;
  label: string;
  period: 'month' | 'year';
  used: number;
  limit: number;
  remaining: number;
  percentUsed: number;
  exceeded: boolean;
}

interface DashboardPayload {
  partner: Record<string, unknown>;
  statistics: {
    monthToDate: {
      totalCalls: number;
      apiCalls?: number;
      errorCalls: number;
      successRate: number;
      avgLatencyMs: number | null;
      webhookCalls: number;
      webhookConfigCalls?: number;
      reportPullCalls: number;
      distinctMsmeAccessed: number;
      topEndpoints: { endpointKey: string; count: number }[];
    };
    yearToDate: {
      totalCalls: number;
      errorCalls: number;
      distinctMsmeAccessed: number;
    };
  };
  usageChart: { date: string; calls: number; errors: number }[];
  quotas?: UsageQuota[];
  billing: Record<string, unknown>;
}

const authHeaders = () => ({
  Authorization: `Bearer ${localStorage.getItem('token')}`,
});

const StatCard: React.FC<{ label: string; value: string | number; hint?: string }> = ({
  label,
  value,
  hint,
}) => (
  <Card variant="outlined" sx={{ height: '100%' }}>
    <CardContent>
      <Typography variant="overline" color="text.secondary">
        {label}
      </Typography>
      <Typography variant="h5" sx={{ fontWeight: 700, mt: 0.5 }}>
        {value}
      </Typography>
      {hint && (
        <Typography variant="caption" color="text.secondary">
          {hint}
        </Typography>
      )}
    </CardContent>
  </Card>
);

const PartnerDashboard: React.FC = () => {
  const [tab, setTab] = useState(0);
  const [dashboard, setDashboard] = useState<DashboardPayload | null>(null);
  const [error, setError] = useState<string | null>(null);

  const loadDashboard = useCallback(async () => {
    try {
      setError(null);
      const res = await axios.get(buildApiUrl('/partner-account/dashboard'), {
        headers: authHeaders(),
      });
      setDashboard(res.data?.data || null);
    } catch (err) {
      const message = axios.isAxiosError(err)
        ? err.response?.data?.message || err.message
        : 'Failed to load dashboard';
      setError(message);
    }
  }, []);

  useEffect(() => {
    loadDashboard();
  }, [loadDashboard]);

  const month = dashboard?.statistics?.monthToDate;
  const billing = dashboard?.billing as {
    estimatedTotalInr?: number;
    estimatedMonthlyPlatformFeeInr?: number;
    overage?: {
      estimatedOverageInr?: number;
      breakdownInr?: Record<string, number>;
    };
    note?: string;
    paymentGateway?: {
      enabled: boolean;
      provider?: string | null;
      mode?: string;
      reason?: string;
    };
    settlementModel?: string;
    currentPeriodUsage?: Record<string, number>;
    usageIncluded?: Record<string, number>;
  } | undefined;

  const exceededQuotas = dashboard?.quotas?.filter((q) => q.exceeded) || [];
  const orgType = String(dashboard?.partner?.organizationType || '');

  const orgTabs: { label: string; key: string; show: boolean }[] = [
    { label: 'Overview', key: 'overview', show: true },
    { label: 'API usage', key: 'usage', show: true },
    { label: 'Quotas & billing', key: 'billing', show: true },
    { label: 'MSME cohort', key: 'cohort', show: true },
    { label: 'Cluster MIS', key: 'mis', show: ['government_accredited_auditor', 'verification_agency', 'bank_incentives_partner'].includes(orgType) },
    { label: 'Verification queue', key: 'verify', show: orgType === 'verification_agency' },
  ].filter((t) => t.show);

  const activeTabKey = orgTabs[tab]?.key || 'overview';

  return (
    <PartnerPortalLayout
      title="Usage & billing"
      subtitle="Monitor API calls, quotas, success rates, and indicative billing for your partner application."
    >
      {error && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>
          {error}
        </Alert>
      )}

      {exceededQuotas.length > 0 && (
        <Alert severity="warning" sx={{ mb: 2 }}>
          Usage quota exceeded for: {exceededQuotas.map((q) => q.label).join(', ')}. Contact{' '}
          support@sustainow.in to review your partnership limits.
        </Alert>
      )}

      <Tabs value={tab} onChange={(_, v) => setTab(v)} sx={{ mb: 2 }} variant="scrollable" scrollButtons="auto">
        {orgTabs.map((t) => (
          <Tab key={t.key} label={t.label} />
        ))}
      </Tabs>

      {activeTabKey === 'overview' && month && (
        <Grid container spacing={2}>
          <Grid item xs={12} sm={6} md={3}>
            <StatCard
              label="API calls (MTD)"
              value={month.apiCalls ?? month.totalCalls}
            />
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <StatCard
              label="Success rate"
              value={`${formatFixed(month.successRate, 1)}%`}
              hint={`${month.errorCalls} errors`}
            />
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <StatCard
              label="Avg latency"
              value={month.avgLatencyMs != null ? `${month.avgLatencyMs} ms` : '—'}
            />
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <StatCard
              label="MSMEs accessed (MTD)"
              value={month.distinctMsmeAccessed}
              hint={`${dashboard?.statistics?.yearToDate?.distinctMsmeAccessed ?? 0} distinct YTD`}
            />
          </Grid>

          {dashboard?.quotas && dashboard.quotas.length > 0 && (
            <Grid item xs={12}>
              <Paper sx={{ p: 2 }}>
                <Typography variant="h6" gutterBottom>
                  Usage quotas
                </Typography>
                <Grid container spacing={2}>
                  {dashboard.quotas.map((quota) => (
                    <Grid item xs={12} md={6} key={quota.metric}>
                      <QuotaMeter quota={quota} />
                    </Grid>
                  ))}
                </Grid>
              </Paper>
            </Grid>
          )}

          <Grid item xs={12} md={6}>
            <Paper sx={{ p: 2 }}>
              <Typography variant="h6" gutterBottom>
                Top endpoints (month)
              </Typography>
              <TableContainer>
                <Table size="small">
                  <TableHead>
                    <TableRow>
                      <TableCell>Endpoint</TableCell>
                      <TableCell align="right">Calls</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {month.topEndpoints?.length ? (
                      month.topEndpoints.map((row) => (
                        <TableRow key={row.endpointKey}>
                          <TableCell>
                            <code>{row.endpointKey}</code>
                          </TableCell>
                          <TableCell align="right">{row.count}</TableCell>
                        </TableRow>
                      ))
                    ) : (
                      <TableRow>
                        <TableCell colSpan={2}>
                          <Typography variant="body2" color="text.secondary">
                            No API traffic recorded yet.
                          </Typography>
                        </TableCell>
                      </TableRow>
                    )}
                  </TableBody>
                </Table>
              </TableContainer>
            </Paper>
          </Grid>

          <Grid item xs={12} md={6}>
            <Paper sx={{ p: 2 }}>
              <Typography variant="h6" gutterBottom>
                Estimated bill (current month)
              </Typography>
              <Typography variant="h4" color="primary.main" sx={{ fontWeight: 700 }}>
                ₹{formatFixed(billing?.estimatedTotalInr ?? 0, 0)}
              </Typography>
              <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
                Platform ₹{formatFixed(billing?.estimatedMonthlyPlatformFeeInr ?? 0, 0)} + overage ₹
                {formatFixed(billing?.overage?.estimatedOverageInr ?? 0, 0)}
              </Typography>
              <Typography variant="caption" display="block" sx={{ mt: 1 }}>
                {billing?.note}
              </Typography>
            </Paper>
          </Grid>
        </Grid>
      )}

      {activeTabKey === 'usage' && dashboard && (
        <Paper sx={{ p: 2 }}>
          <Typography variant="h6" gutterBottom>
            Daily API volume (last 14 days)
          </Typography>
          <TableContainer>
            <Table size="small">
              <TableHead>
                <TableRow>
                  <TableCell>Date</TableCell>
                  <TableCell align="right">Calls</TableCell>
                  <TableCell align="right">Errors</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {dashboard.usageChart?.length ? (
                  dashboard.usageChart.map((row) => (
                    <TableRow key={row.date}>
                      <TableCell>{row.date}</TableCell>
                      <TableCell align="right">{row.calls}</TableCell>
                      <TableCell align="right">{row.errors}</TableCell>
                    </TableRow>
                  ))
                ) : (
                  <TableRow>
                    <TableCell colSpan={3}>
                      <Typography variant="body2" color="text.secondary">
                        No usage data for this period.
                      </Typography>
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </TableContainer>
          <StackWrapStats month={month} />
        </Paper>
      )}

      {activeTabKey === 'billing' && billing && (
        <Grid container spacing={2}>
          <Grid item xs={12}>
            <Alert severity={billing.paymentGateway?.enabled ? 'success' : 'info'}>
              {billing.paymentGateway?.enabled
                ? `Online checkout is enabled for this partner account via ${billing.paymentGateway.provider || 'the configured payment gateway'}.`
                : billing.paymentGateway?.reason ||
                  'Partner billing is settled through contract invoicing. Direct Razorpay checkout is available for MSME plan purchases.'}
            </Alert>
          </Grid>
          <Grid item xs={12} md={6}>
            <Paper sx={{ p: 2 }}>
              <Typography variant="h6" gutterBottom>
                Current period usage
              </Typography>
              <UsageRow
                label="API calls (month)"
                used={billing.currentPeriodUsage?.apiCalls}
                limit={billing.usageIncluded?.apiCallsPerMonth}
              />
              <UsageRow
                label="Webhook events (month)"
                used={billing.currentPeriodUsage?.webhookEvents}
                limit={billing.usageIncluded?.webhookEventsPerMonth}
              />
              <UsageRow
                label="Report pulls (month)"
                used={billing.currentPeriodUsage?.reportPulls}
                limit={billing.usageIncluded?.reportPullsPerMonth}
              />
              <UsageRow
                label="Distinct MSMEs (year)"
                used={billing.currentPeriodUsage?.distinctMsmeAccessedYear}
                limit={billing.usageIncluded?.msmeMonitoredPerYear}
              />
            </Paper>
          </Grid>
          <Grid item xs={12} md={6}>
            <Paper sx={{ p: 2 }}>
              <Typography variant="h6" gutterBottom>
                Billing summary
              </Typography>
              <Typography variant="body2">
                Contract (annual): ₹{formatFixed((billing as { contractAnnualFeeInr?: number }).contractAnnualFeeInr ?? 0, 0)}
              </Typography>
              <Typography variant="body2" sx={{ mt: 1 }}>
                Monthly platform (est.): ₹{formatFixed(billing.estimatedMonthlyPlatformFeeInr ?? 0, 0)}
              </Typography>
              <Typography variant="body2" sx={{ mt: 1 }}>
                Overage (est.): ₹{formatFixed(billing.overage?.estimatedOverageInr ?? 0, 2)}
              </Typography>
              <Typography variant="body2" sx={{ mt: 1 }}>
                Settlement: {billing.settlementModel === 'partner_contract_invoice' ? 'Contract invoice' : billing.settlementModel || 'Not configured'}
              </Typography>
              {billing.overage?.breakdownInr && (
                <Box sx={{ mt: 1 }}>
                  {Object.entries(billing.overage.breakdownInr).map(([key, value]) => (
                    <Typography key={key} variant="caption" display="block" color="text.secondary">
                      {key}: ₹{formatFixed(value, 2)}
                    </Typography>
                  ))}
                </Box>
              )}
              <Chip label={`Total est. ₹${formatFixed(billing.estimatedTotalInr ?? 0, 0)}`} color="primary" sx={{ mt: 2 }} />
              <Typography variant="caption" display="block" sx={{ mt: 2 }}>
                {billing.note}
              </Typography>
            </Paper>
          </Grid>
        </Grid>
      )}

      {activeTabKey === 'cohort' ? <PartnerMsmeCohortPanel /> : null}
      {activeTabKey === 'mis' ? <PartnerClusterMisPanel /> : null}
      {activeTabKey === 'verify' ? <PartnerVerificationQueuePanel /> : null}
    </PartnerPortalLayout>
  );
};

const QuotaMeter: React.FC<{ quota: UsageQuota }> = ({ quota }) => {
  const progress = Math.min(quota.percentUsed, 100);
  const color = quota.exceeded ? 'error' : progress >= 80 ? 'warning' : 'primary';

  return (
    <Box>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 0.5 }}>
        <Typography variant="body2">
          {quota.label}{' '}
          <Typography component="span" variant="caption" color="text.secondary">
            ({quota.period})
          </Typography>
        </Typography>
        <Typography variant="body2" color="text.secondary">
          {quota.used} / {quota.limit}
        </Typography>
      </Box>
      <LinearProgress
        variant="determinate"
        value={progress}
        color={color}
        sx={{ height: 8, borderRadius: 1 }}
      />
    </Box>
  );
};

const UsageRow: React.FC<{ label: string; used?: number; limit?: number }> = ({
  label,
  used = 0,
  limit = 0,
}) => (
  <Box sx={{ display: 'flex', justifyContent: 'space-between', py: 0.75 }}>
    <Typography variant="body2">{label}</Typography>
    <Typography variant="body2" color="text.secondary">
      {used} / {limit}
    </Typography>
  </Box>
);

const StackWrapStats: React.FC<{ month?: DashboardPayload['statistics']['monthToDate'] }> = ({
  month,
}) => {
  if (!month) return null;
  return (
    <Box sx={{ mt: 2, display: 'flex', gap: 1, flexWrap: 'wrap' }}>
      <Chip size="small" label={`Webhook events: ${month.webhookCalls}`} />
      <Chip size="small" label={`Report pulls: ${month.reportPullCalls}`} />
      {month.webhookConfigCalls != null && month.webhookConfigCalls > 0 && (
        <Chip size="small" variant="outlined" label={`Webhook config calls: ${month.webhookConfigCalls}`} />
      )}
    </Box>
  );
};

export default PartnerDashboard;
