import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Chip,
  CircularProgress,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
} from '@mui/material';
import axios from 'axios';
import { buildApiUrl } from '../../config/apiConfig';

const authHeaders = () => ({ Authorization: `Bearer ${localStorage.getItem('token')}` });

const PartnerClusterMisPanel: React.FC = () => {
  const [data, setData] = useState<{
    summary?: Record<string, number>;
    byIndustry?: { industry: string; count: number }[];
  } | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const res = await axios.get(buildApiUrl('/partner-account/cluster-mis'), { headers: authHeaders() });
      setData(res.data?.data || null);
    } catch (e) {
      setError(axios.isAxiosError(e) ? e.response?.data?.message || e.message : 'Failed to load MIS');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  if (loading) return <CircularProgress />;
  if (error) return <Alert severity="error">{error}</Alert>;

  const s = data?.summary || {};

  return (
    <Box>
      <Typography variant="h6" sx={{ fontWeight: 700, mb: 2 }}>Cluster MIS (aggregated)</Typography>
      <Stack direction="row" spacing={2} flexWrap="wrap" useFlexGap sx={{ mb: 3 }}>
        {[
          ['Total MSMEs', s.totalMsmes],
          ['Verified', s.verifiedMsmes],
          ['Avg carbon score', s.averageCarbonScore],
        ].map(([label, value]) => (
          <Chip key={String(label)} label={`${label}: ${value ?? '—'}`} variant="outlined" />
        ))}
      </Stack>
      <TableContainer>
        <Table size="small">
          <TableHead>
            <TableRow>
              <TableCell>Industry</TableCell>
              <TableCell>MSME count</TableCell>
            </TableRow>
          </TableHead>
          <TableBody>
            {(data?.byIndustry || []).map((row) => (
              <TableRow key={row.industry}>
                <TableCell>{row.industry}</TableCell>
                <TableCell>{row.count}</TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </TableContainer>
      <Button sx={{ mt: 2 }} size="small" onClick={load}>Refresh</Button>
    </Box>
  );
};

export default PartnerClusterMisPanel;
